import styles from "./operations-insights.module.css";

type Tone = "green" | "orange" | "red" | "blue" | "gray";
type Metric = { label: string; value: string; note?: string; tone?: Tone; icon?: ReactNode };

function cx(...values: Array<string | false | null | undefined>) {
  return values.filter(Boolean).join(" ");
}

function Button({ children, href, primary, success, danger, compact }: { children: ReactNode; href?: string; primary?: boolean; success?: boolean; danger?: boolean; compact?: boolean }) {
  const className = cx(styles.button, primary && styles.primary, success && styles.success, danger && styles.danger, compact && styles.compact);
  return href ? <Link className={className} href={href}>{children}</Link> : <button className={className} type="button">{children}</button>;
}

function Pill({ children, tone = "blue" }: { children: ReactNode; tone?: Tone }) {
  return <span className={cx(styles.pill, styles[tone])}>{children}</span>;
}

function Person({ name, role }: { name: string; role?: string }) {
  const initials = name.split(" ").map((part) => part[0]).join("").slice(0, 2);
  return <span className={styles.person}><span className={styles.avatar} style={{ display: "grid", placeItems: "center", background: "#ece9ff", color: "#3415df", fontSize: 8, fontWeight: 800 }}>{initials}</span><span><span className={styles.personName}>{name}</span>{role && <span className={styles.personRole}>{role}</span>}</span></span>;
}

function Header({ title, subtitle, crumbs, actions }: { title: string; subtitle: string; crumbs?: string; actions?: ReactNode }) {
  return <><div className={styles.header}><div>{crumbs && <div className={styles.crumbs}>{crumbs}</div>}<h1 className={styles.title}>{title}</h1><p className={styles.subtitle}>{subtitle}</p></div><div className={styles.actions}>{actions}</div></div></>;
}

function Metrics({ items, columns }: { items: Metric[]; columns?: number }) {
  return <div className={styles.metrics} style={{ "--metric-cols": columns ?? items.length } as CSSProperties}>{items.map((item) => <article className={styles.metric} key={item.label}><div className={styles.metricTop}>{item.icon && <span className={styles.metricIcon}>{item.icon}</span>}<span className={styles.label}>{item.label}</span></div><div className={cx(styles.metricValue, item.tone && styles[item.tone])}>{item.value}</div>{item.note && <div className={cx(styles.delta, item.tone === "red" && styles.bad, item.tone === "orange" && styles.warn)}>{item.note}</div>}</article>)}</div>;
}

function Tabs({ items, active = 0 }: { items: string[]; active?: number }) {
  return <nav className={styles.tabs}>{items.map((item, index) => <button className={cx(styles.tab, index === active && styles.active)} key={item} type="button">{item}</button>)}</nav>;
}

function Filters({ labels = ["All Clients", "All Projects", "All Owners", "All Statuses"] }: { labels?: string[] }) {
  return <div className={styles.filters}><div className={styles.input}><Search size={13}/> Search records...</div>{labels.map((label) => <button className={styles.select} key={label} type="button">{label}<span>⌄</span></button>)}<Button compact><Filter size={12}/> More Filters</Button></div>;
}

function Card({ title, action, children, className }: { title: string; action?: string; children: ReactNode; className?: string }) {
  return <section className={cx(styles.card, className)}><div className={styles.cardTitle}><span>{title}</span>{action && <button className={styles.cardLink} type="button">{action}</button>}</div>{children}</section>;
}

function DataTable({ columns, rows, minWidth = 980, selected = -1 }: { columns: string[]; rows: ReactNode[][]; minWidth?: number; selected?: number }) {
  return <div className={styles.tableWrap}><div className={styles.tableScroll}><table className={styles.table} style={{ minWidth }}><thead><tr>{columns.map((column) => <th key={column}>{column}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr className={index === selected ? styles.selected : undefined} key={index}>{row.map((cell, cellIndex) => <td key={cellIndex}>{cell}</td>)}</tr>)}</tbody></table></div><Pagination count={rows.length}/></div>;
}

function Pagination({ count }: { count: number }) {
  return <div className={styles.pagination}><span>Showing 1 to {count} of {count * 6 + 2} records</span><span className={styles.pages}><button className={styles.pageButton} type="button"><ChevronLeft size={12}/></button>{[1, 2, 3].map((page) => <button className={cx(styles.pageButton, page === 1 && styles.active)} key={page} type="button">{page}</button>)}<button className={styles.pageButton} type="button"><ChevronRight size={12}/></button></span></div>;
}

function Donut({ value, label = "Total", tone = "76%" }: { value: string; label?: string; tone?: string }) {
  return <div className={styles.donut} style={{ "--donut": tone } as CSSProperties}><div className={styles.donutInner}><div className={styles.donutValue}>{value}</div><div className={styles.donutLabel}>{label}</div></div></div>;
}

function LineChart({ alt = false }: { alt?: boolean }) {
  return <div className={styles.chart}><svg viewBox="0 0 600 150" preserveAspectRatio="none"><path className={styles.chartGrid} d="M0 25H600M0 60H600M0 95H600M0 130H600"/><path className={alt ? styles.chartLineAlt : styles.chartLine} d="M0 124 C45 110 62 92 105 96 S165 75 205 79 S272 50 320 58 S390 43 430 46 S515 25 600 18"/></svg></div>;
}

function BarRows({ items }: { items: Array<[string, number, string?]> }) {
  return <div className={styles.bars}>{items.map(([label, width, value]) => <div className={styles.barRow} key={label}><span>{label}</span><span className={styles.barTrack}><span className={styles.barFill} style={{ width: `${width}%` }}/></span><strong>{value ?? `${width}%`}</strong></div>)}</div>;
}

function QuickActions({ items }: { items: Array<[string, ReactNode]> }) {
  return <div className={styles.grid2}>{items.map(([label, icon]) => <Button compact key={label}>{icon}{label}</Button>)}</div>;
}

